A=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(int)
r,g,b=A[:,:,0],A[:,:,1],A[:,:,2]
M=(r>130)&(r>g*1.4)&(r>b*1.5)
for y in range(144):
 xs=np.where(M[y])[0]
 if len(xs):
  # contiguous runs len>=2
  runs=[]; st=pr=xs[0]
  for x in xs[1:]:
   if x>pr+1:
    if pr-st+1>=2:runs.append((st,pr))
    st=x
   pr=x
  if pr-st+1>=2:runs.append((st,pr))
  if runs: print(y, runs)
