from PIL import Image
import numpy as np
A=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(float)
# Calculate plausible rectangular structure edges using mean absolute adjacent diff within region, scanning candidate boundary x/y
for axis in ['x','y']:
 scores=[]
 if axis=='x':
  for x in range(120,241):
   scores.append((np.abs(A[60:100,x+1]-A[60:100,x]).mean(),x))
 else:
  for y in range(50,144):
   scores.append((np.abs(A[y+1,100:235]-A[y,100:235]).mean(),y))
 print(axis, sorted(scores,reverse=True)[:30])
